-- Port verbatim de "BDD - Accepter invitation Workspace"
-- Params: $1 user_id, $2 token (clair)
WITH p AS (SELECT NULLIF($1::text,'')::uuid AS user_id,$2::text AS token), claimed AS (SELECT wi.* FROM p JOIN public.workspace_invitations wi ON wi.token_hash=encode(digest(p.token,'sha256'),'hex') AND wi.accepted_at IS NULL AND wi.revoked_at IS NULL AND wi.expires_at>now() JOIN public.app_users u ON u.id=p.user_id AND lower(u.email)=lower(wi.email) FOR UPDATE), member AS (INSERT INTO public.workspace_members(workspace_id,user_id,role,status,invited_by) SELECT c.workspace_id,p.user_id,c.role,'active',c.invited_by FROM claimed c CROSS JOIN p ON CONFLICT(workspace_id,user_id) DO UPDATE SET role=CASE WHEN public.workspace_members.role='owner' THEN 'owner' ELSE EXCLUDED.role END,status='active',updated_at=now() RETURNING workspace_id,user_id), done AS (UPDATE public.workspace_invitations wi SET accepted_at=now(),updated_at=now() FROM claimed c WHERE wi.id=c.id AND EXISTS(SELECT 1 FROM member) RETURNING wi.id), active AS (UPDATE public.app_users u SET last_workspace_id=m.workspace_id FROM member m WHERE u.id=m.user_id RETURNING m.workspace_id) SELECT EXISTS(SELECT 1 FROM done) AS success,COALESCE((SELECT workspace_id::text FROM active),'') AS workspace_id,CASE WHEN EXISTS(SELECT 1 FROM done) THEN 'Invitation acceptée.' ELSE 'Invitation invalide, expirée ou destinée à une autre adresse email.' END AS message;